mapper.select:
SELECT id
FROM student
WHERE id = #{studentId}
  AND school_id = #{schoolId}
FOR UPDATE

SELECT id
FROM course_offering
WHERE id = #{offeringId}
  AND school_id = #{schoolId}
FOR UPDATE

SELECT COUNT(*)
FROM course_evaluation
WHERE offering_id = #{offeringId}
  AND student_id = #{studentId}

SELECT 
FROM course_evaluation ce
JOIN school s ON s.id = ce.school_id
JOIN course_offering o ON o.id = ce.offering_id
LEFT JOIN academic_term at ON at.id = o.term_id
JOIN course c ON c.id = o.course_id
JOIN teacher t ON t.id = o.teacher_id
JOIN student st ON st.id = ce.student_id
JOIN guardian g ON g.id = ce.guardian_id


        ce.school_id = #{schoolId}


        AND (
            o.term_id = #{termId}
            OR (
                o.term_id IS NULL
                AND EXISTS (
                    SELECT 1
                    FROM academic_term legacy_term
                    WHERE legacy_term.id = #{termId}
                      AND o.term IN (
                          legacy_term.term_code,
                          legacy_term.term_name
                      )
                )
            )
        )


        AND c.category = #{category}


        AND ce.rating >= #{minRating}


        AND ce.rating <= #{maxRating}


        AND ce.submitted_at >= #{submittedFrom}


        AND ce.submitted_at <= #{submittedTo}


ORDER BY ce.submitted_at DESC, ce.id DESC

SELECT COUNT(ce.id) AS evaluationCount,
       COALESCE(ROUND(AVG(ce.rating), 2), 0) AS averageRating,
       COALESCE(ROUND(
           100.0 * SUM(CASE WHEN ce.rating >= 4 THEN 1 ELSE 0 END)
           / NULLIF(COUNT(ce.id), 0),
           1
       ), 0) AS satisfactionRate,
       COALESCE(SUM(
           CASE WHEN ce.rating = 5 THEN 1 ELSE 0 END
       ), 0) AS rating5Count,
       COALESCE(SUM(
           CASE WHEN ce.rating = 4 THEN 1 ELSE 0 END
       ), 0) AS rating4Count,
       COALESCE(SUM(
           CASE WHEN ce.rating = 3 THEN 1 ELSE 0 END
       ), 0) AS rating3Count,
       COALESCE(SUM(
           CASE WHEN ce.rating = 2 THEN 1 ELSE 0 END
       ), 0) AS rating2Count,
       COALESCE(SUM(
           CASE WHEN ce.rating = 1 THEN 1 ELSE 0 END
       ), 0) AS rating1Count
FROM course_evaluation ce
JOIN course_offering o ON o.id = ce.offering_id
JOIN course c ON c.id = o.course_id


        ce.school_id = #{schoolId}


        AND (
            o.term_id = #{termId}
            OR (
                o.term_id IS NULL
                AND EXISTS (
                    SELECT 1
                    FROM academic_term legacy_term
                    WHERE legacy_term.id = #{termId}
                      AND o.term IN (
                          legacy_term.term_code,
                          legacy_term.term_name
                      )
                )
            )
        )


        AND c.category = #{category}


        AND ce.submitted_at >= #{submittedFrom}


        AND ce.submitted_at <= #{submittedTo}
